{
  "@context": [
    "http://www.w3.org/ns/odrl.jsonld",
    {
      "dc": "http://purl.org/dc/elements/1.1/",
      "dcterms": "http://purl.org/dc/terms/",
      "foaf": "http://xmlns.com/foaf/0.1/",
      "xsd": "http://www.w3.org/2001/XMLSchema#",
      "ex": "http://example.org/modelcard/terms#"
    }
  ],
  "@type": "odrl:Policy",
  "uid": "http://example.org/policy/chronos-2",
  "profile": "http://example.org/odrl/profile/modelcard",
  "target": {
    "@id": "http://example.org/asset/chronos-2",
    "@type": "odrl:Asset",
    "dc:title": "Chronos-2",
    "dc:creator": {
      "@id": "http://example.org/party/amazon"
    },
    "dc:type": "Time series foundation model (encoder-only, zero-shot forecasting)",
    "ex:hardware": "GPU and CPU inference; over 300 time series forecasts per second on a single A10G GPU",
    "ex:software": "Python package chronos-forecasting 2.0 or later; deployment on Amazon SageMaker with AutoGluon-Cloud (recommended) or SageMaker JumpStart",
    "ex:evaluationDatasets": "fev-bench, GIFT-Eval, Chronos Benchmark II",
    "ex:evaluationPerformance": "State-of-the-art zero-shot accuracy among public models on fev-bench, GIFT-Eval and Chronos Benchmark II",
    "ex:trainingDataset": "Subset of the Chronos Datasets (excluding the test portion of datasets that overlap with GIFT-Eval); subset of GIFT-Eval Pretrain; synthetic univariate and multivariate data",
    "ex:trainingAlgorithm": "120M parameters, encoder-only, inspired by the T5 encoder, with group attention",
    "ex:evaluationFactors": "Chronos-2 supports univariate, multivariate and covariate-informed forecasting in a single architecture and produces multi-step-ahead quantile forecasts",
    "ex:limitations": "For production use, deploy Chronos-2 on Amazon SageMaker, preferably with AutoGluon-Cloud; maximum context length is 8192 and maximum prediction length is 1024"
  },
  "party": [
    {
      "@id": "http://example.org/party/amazon",
      "foaf:name": "Amazon",
      "odrl:role": "odrl:assigner"
    },
    {
      "@id": "http://example.org/party/time-series-analysts",
      "foaf:name": "Time series analysts",
      "odrl:role": "odrl:assignee"
    }
  ],
  "permission": [
    {
      "@type": "odrl:Permission",
      "action": "odrl:use",
      "constraint": [
        {
          "leftOperand": "ex:primaryIntendedUseCase",
          "operator": "odrl:eq",
          "rightOperand": "Zero-shot forecasting of univariate time series; multivariate forecasting; forecasting informed by past-only and known-future covariates; cross-learning across related series"
        }
      ]
    }
  ],
  "prohibition": [
    {
      "@type": "odrl:Prohibition",
      "action": "odrl:use",
      "constraint": [
        {
          "odrl:or": [
            {
              "leftOperand": "ex:misuseCase",
              "operator": "odrl:eq",
              "rightOperand": "Unintended use cases not covered by the primary intended use cases"
            }
          ]
        }
      ]
    }
  ],
  "duty": [
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:regulatoryAdherence",
          "operator": "odrl:eq",
          "rightOperand": "Adheres to AWS security and privacy policies"
        }
      ]
    },
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:regulatoryCompliance",
          "operator": "odrl:eq",
          "rightOperand": "Aligned with AWS regulatory compliance requirements"
        }
      ]
    }
  ]
}

{
  "@context": [
    "http://www.w3.org/ns/odrl.jsonld",
    {
