  "@type": "odrl:Policy",
  "uid": "http://example.org/policy/deepsseek-v4-pro",
  "profile": "http://example.org/odrl/profile/modelcard",
  "target": {
    "@id": "http://example.org/asset/deepsseek-v4-pro",
    "@type": "odrl:Asset",
    "dc:title": "DeepSeek-V4-Pro",
    "dc:creator": {
      "@id": "http://example.org/party/deepsseek-ai"
    },
    "dc:type": "Mixture-of-Experts language model",
    "ex:architecture": "1.6T total and 49B activated parameters, one-million-token context length, hybrid attention (Compressed Sparse Attention and Heavily Compressed Attention), Manifold-Constrained Hyper-Connections, FP4 and FP8 mixed precision",
    "ex:description": "DeepSeek-V4-Pro is a preview of the DeepSeek-V4 series of Mixture-of-Experts language models, designed for efficient long-context use with three reasoning effort modes.",
    "dcterms:license": "MIT",
    "dcterms:hasVersion": "DeepSeek-V4-Pro (preview)"
  },
  "party": [
    {
      "@id": "http://example.org/party/deepsseek-ai",
      "foaf:name": "DeepSeek-AI",
      "odrl:role": "odrl:assigner"
    },
    {
      "@id": "http://example.org/party/language-model-users",
      "foaf:name": "Language model users",
      "odrl:role": "odrl:assignee"
    }
  ],
  "permission": [
    {
      "@type": "odrl:Permission",
      "action": "odrl:use",
      "constraint": [
        {
          "leftOperand": "ex:intendedUseCase",
          "operator": "odrl:eq",
          "rightOperand": "Knowledge and reasoning tasks; Coding; Long-context tasks of up to one million tokens; Agentic tasks; Non-think mode for routine daily tasks and low-risk decisions; Think high mode for complex problem solving and planning; Think max mode for exploring the boundary of reasoning capability"
        }
      ]
    }
  ],
  "prohibition": [
    {
      "@type": "odrl:Prohibition",
      "action": "odrl:use",
      "constraint": [
        {
          "odrl:or": [
            {
              "leftOperand": "ex:misuseCase",
              "operator": "odrl:eq",
              "rightOperand": "Unintended use cases not listed above"
            }
          ]
        }
      ]
    }
  ],
  "duty": [
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:caveatsAndRecommendations",
          "operator": "odrl:eq",
          "rightOperand": "For local deployment, set the sampling parameters to temperature 1.0 and top_p 1.0; For the think max mode, set the context window to at least 384K tokens; The release has no Jinja chat template, so messages are encoded with the provided encoding scripts"
        }
      ]
    },
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:securityMeasures",
          "operator": "odrl:eq",
          "rightOperand": "Deployment is hardware-bound; model load requires a key"
        }
      ]
    }
  ]
}

