    "ex:architecture": "12 layers, embedding size 384, initialized from microsoft/Multilingual-MiniLM-L12-H384",
    "ex:description": "Multilingual-E5-small encodes queries and passages as text embeddings for retrieval and similarity tasks in 100 languages.",
    "dcterms:license": "MIT"
  },
  "party": [
    {
      "@id": "http://example.org/party/intfloat",
      "foaf:name": "intfloat",
      "odrl:role": "odrl:assigner"
    },
    {
      "@id": "http://example.org/party/researchers-and-developers",
      "foaf:name": "Researchers and developers",
      "odrl:role": "odrl:assignee"
    }
  ],
  "permission": [
    {
      "@type": "odrl:Permission",
      "action": "odrl:use",
      "constraint": [
        {
          "leftOperand": "ex:primaryIntendedUseCase",
          "operator": "odrl:eq",
          "rightOperand": "Passage retrieval in open question answering and ad-hoc information retrieval; semantic similarity; bitext mining and paraphrase retrieval; embeddings as features for linear probing classification and clustering"
        }
      ]
    }
  ],
  "prohibition": [
    {
      "@type": "odrl:Prohibition",
      "action": "odrl:use",
      "constraint": [
        {
          "odrl:or": [
            {
              "leftOperand": "ex:misuseCase",
              "operator": "odrl:eq",
              "rightOperand": "Unintended use cases not specified"
            }
          ]
        }
      ]
    }
  ],
  "duty": [
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:caveatsAndRecommendations",
          "operator": "odrl:eq",
          "rightOperand": "Add the prefixes \"query: \" and \"passage: \" to input texts as in training, otherwise performance degrades: use both for asymmetric tasks such as passage retrieval and \"query: \" only for symmetric tasks and for features; compare relative order of cosine similarity scores rather than absolute values, which fall between 0.7 and 1.0"
        }
      ]
    }
  ]
}

