  ],
  "@type": "odrl:Policy",
  "uid": "http://example.org/policy/llama-3-2",
  "profile": "http://example.org/odrl/profile/modelcard",
  "target": {
    "@id": "http://example.org/asset/llama-3-2",
    "@type": "odrl:Asset",
    "dc:title": "Llama 3.2",
    "dc:creator": {
      "@id": "http://example.org/party/meta"
    },
    "dc:type": "Multilingual large language model (text in, text out)",
    "dcterms:hasVersion": "Llama 3.2 1B and 3B, pretrained and instruction-tuned (text only)",
    "ex:hardware": "Meta's custom-built GPU cluster with H100-80GB GPUs (700W TDP); 830k GPU hours of training",
    "ex:software": "Custom training libraries",
    "ex:evaluationMetrics": "MMLU, AGIEval, ARC-Challenge, SQuAD, QuAC, DROP, Needle in Haystack, IFEval, GSM8K, MATH, GPQA, Hellaswag, BFCL V2, Nexus, InfiniteBench, MGSM and multilingual MMLU",
    "ex:evaluationPerformance": "Instruction-tuned 3B: MMLU 63.4, IFEval 77.4, GSM8K 77.7, MATH 47.3, ARC-C 78.6; instruction-tuned 1B: MMLU 49.3, IFEval 59.5, GSM8K 44.4",
    "ex:evaluationDatasets": "Standard automatic benchmarks run with Meta's internal evaluations library; dedicated adversarial evaluation datasets for safety",
    "ex:trainingAlgorithm": "Auto-regressive optimized transformer; supervised fine-tuning and reinforcement learning with human feedback",
    "ex:trainingDataset": "Up to 9 trillion tokens of publicly available online data with a cutoff of December 2023, plus logits from Llama 3.1 8B and 70B",
    "ex:trainingProcedure": "Pretraining with logits from Llama 3.1 8B and 70B as token-level targets, pruning and knowledge distillation, then several rounds of supervised fine-tuning, rejection sampling and direct preference optimization",
    "ex:typeOfBias": "The model may in some instances produce inaccurate, biased or other objectionable responses",
    "ex:riskFactors": "Testing has not covered all scenarios and outputs cannot be predicted in advance; critical risk areas are chemical, biological, radiological, nuclear and explosive weapons, child safety and cyber attacks; small models in constrained environments have a different safety and helpfulness tradeoff",
    "ex:riskMitigation": "Recurring red teaming exercises whose findings improve benchmarks and safety tuning datasets; an output reporting mechanism and a bug bounty program",
    "ex:safetyMeasures": "Safety fine-tuning with human-generated and synthetic data, LLM-based classifiers to select prompts and responses, refusal and tone tuning, and safeguards provided to the community (Llama Guard, Prompt Guard and Code Shield)",
    "ex:safetyAndSecurityPolicy": "Developed following the Responsible Use Guide; use is subject to the Acceptable Use Policy",
    "ex:prohibitedDomains": "Use in any manner that violates applicable laws or regulations (including trade compliance laws); use prohibited by the Acceptable Use Policy and the Llama 3.2 Community License; use in languages beyond those explicitly supported",
    "ex:limitations": "Static model trained on an offline dataset; only English, German, French, Italian, Portuguese, Hindi, Spanish and Thai are officially supported; testing has not covered all scenarios",
    "ex:biasMitigation": "",
    "ex:privacyConcerns": "",
    "ex:privacyPolicy": "",
    "ex:securityMeasures": "",
    "ex:riskSeverity": "",
    "ex:unintendedUsers": "",
    "ex:regulatoryAdherence": "",
    "ex:regulatoryCompliance": "",
