      "action": "odrl:inform",
      "constraint": [
        {
          "leftOperand": "ex:safetyAndSecurityPolicy",
          "operator": "odrl:eq",
          "rightOperand": "Developed following the Responsible Use Guide; use is subject to the Acceptable Use Policy"
        }
      ]
    },
    {
      "@type": "odrl:Duty",
      "action": "odrl:inform",
      "constraint": [
